    public void solve() {
    	int N = ni();
    	int[] H = new int[N];
    	boolean f = true;
    	for (int i = 0; i < N; i++) {
			H[i] = ni();
			if(H[i] > 0)	f = false;
		}
    	if(f) {
    		out.println(0);
    		return;
    	}
