    // ======================================================================
    static class Solver {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
        	int ans = 0;
            int N = in.nextInt();
//        	char[] s = in.nextDChar();

            int min = 2000000000;
            int max = -1;
            int a = 0;
            for(int i=0; i < N; i++) {
                a = in.nextInt();
